/**
 * Mushaf page layout — the data behind the font-rendered reader (v2.8.0).
 *
 * `data/mushafLayoutV2.json` is generated by `scripts/mushaf/build_qcf_assets.py`
 * from the QPC v2 word data. For every one of the 604 pages it holds the 15
 * printed lines: what kind of line it is, the words on it (as the codepoints
 * of the page's own font, where one glyph is one word), which ayah each word
 * belongs to, and how wide the line is in ems of that font.
 *
 * Two things make the page look like the print rather than like a web page:
 *
 * - **`measure`** — the width of the page's widest line, in ems. The reader
 *   sets `fontSize = availableWidth / measure`, so that line spans the page
 *   exactly and every page ends up the same physical width even though the
 *   fonts are drawn at different design sizes.
 * - **`natural`** — each line's own width in ems. A full line is within ~2% of
 *   the measure, so ordinary word spacing closes the gap invisibly; lines that
 *   close a surah are marked `centered` and are not stretched at all.
 *
 * The raw JSON is kept in its compact on-disk shape and decoded per page on
 * demand — decoding all 604 up front would cost time and memory the reader
 * never needs, since it only ever shows a handful of pages.
 */
import { riwayahById, type RiwayahId } from './riwayat';

type RawSegment = [number, number, number, number] | [number, number, number, number, number];

type RawLine = {
  t: 'a' | 's' | 'b';
  /** Ayah lines: words as font codepoints, separated by "|". */
  x?: string;
  /** Ayah lines: [surah, ayah, firstWordPosition, wordCount, isEnd?] runs. */
  w?: RawSegment[];
  /** Ayah lines: natural width in ems. */
  n?: number;
  /** Ayah lines: each word's advance width, in ems. */
  a?: number[];
  /** Ayah lines: 1 when the line closes a surah and must not be stretched. */
  c?: 1;
  /** Surah/basmalah lines: which surah. */
  s?: number;
};

type RawPage = { p: number; m: number; l: RawLine[] };

export type MushafWord = {
  /** The codepoint(s) to draw with the page font. */
  text: string;
  surah: number;
  ayah: number;
  /** 1-based word position within the ayah (matches the word timing data). */
  position: number;
  /** True for the ayah-number medallion, which QPC treats as a word. */
  isEnd: boolean;
  /**
   * The word's advance width in ems — how far the pen moves, which is NOT
   * how wide the word looks. Several QPC glyphs draw ink far past their
   * advance so they interlock with their neighbours (page 1's basmalah is
   * the clearest). That is why a line is drawn as one text run and taps are
   * resolved against these advances instead of per-word views.
   */
  advance: number;
};

export type MushafLine =
  // Split rather than `kind: 'surah' | 'basmalah'` so the discriminant
  // narrows cleanly at the call sites that switch on it.
  | { kind: 'surah'; surah: number }
  | { kind: 'basmalah'; surah: number }
  | {
      kind: 'ayah';
      words: MushafWord[];
      /** Natural width in ems of the page font. */
      natural: number;
      /** Closes a surah — centred, never stretched. */
      centered: boolean;
    };

export type MushafPageLayout = {
  page: number;
  /** Width of the page's widest line, in ems of the page font. */
  measure: number;
  lines: MushafLine[];
};

/** Lines on a standard page. Pages 1–2 are ornamental plates with fewer. */
export const MUSHAF_LINES_PER_PAGE = 15;

// ---------------------------------------------------------------------------
// Line spacing
//
// `natural` is the sum of the glyph ADVANCES only — the QPC page fonts carry
// no space glyph, so the gap between two words is entirely the renderer's to
// supply. Everything below is the model for that gap, kept here (and free of
// React Native) so a test can replay exactly what the reader draws.
// ---------------------------------------------------------------------------

/**
 * Nominal word space, in ems. The print's own space is not recorded anywhere
 * in the data, so we take the page's tightest line — the one with the most
 * ink per gap — to be set at this space, which fixes the width of the printed
 * text block and therefore the space every other line needs.
 */
export const WORD_SPACE_EM = 0.25;

/**
 * The band the word space may move inside (`docs/mushaf-fidelity-rules.md`).
 * Below the minimum the QPC letterforms, which interlock by design, start to
 * touch. Above the maximum a line stops looking like a line of the mushaf and
 * starts looking like justified web text pulled apart, so it is centred at its
 * natural width instead — short lines are meant to be short.
 */
export const WORD_SPACE_MIN_EM = 0.2;
export const WORD_SPACE_MAX_EM = 0.75;

/**
 * Advance of `space` (U+0020) and no-break space (U+00A0) in the bundled
 * `AmiriQuran.ttf`, in ems — read out of the shipped binary, which is byte
 * identical on both platforms:
 *
 *     hmtx['space'] / head.unitsPerEm  ==  292 / 1000
 *
 * The renderer draws every gap in that font, at a size it derives from this
 * number, so the drawn width of a line is the width we computed rather than
 * whatever the platform's fallback face happens to use. `verify_mushaf.py`
 * re-reads the font and fails if this drifts.
 */
export const MUSHAF_SPACE_ADVANCE_EM = 0.292;

/**
 * Slack carried by the box a line is drawn in, in ems, reserved out of the
 * page block so a line's box can never be wider than the block it sits in.
 *
 * This is not a fudge factor, it is the difference between a correct page and
 * a page with a word missing from every line. Android lays a single line out
 * by BREAKING it, and when nothing else will fit it breaks between glyphs —
 * and in QPC a glyph is a whole word. So a line that comes out one sub-pixel
 * wider than its box does not clip a hair of ink, it silently loses its last
 * word (page 49, every line, verified on a Pixel). Measured on device, the
 * drawn width tracks the computed width to within ~0.05 em; half an em of
 * reserve is twenty times that, and also gives the ink QPC glyphs throw past
 * their advance somewhere to land at the margins.
 */
export const MUSHAF_LINE_BOX_SLACK_EM = 0.5;

/**
 * The QPC page fonts' vertical metrics, in ems: what the platform lays a
 * line out with (hhea ascent 1.2 / descent 0.6 — a handful of pages say
 * 1.1236 / 0.52, which only makes them safer), and how far the INK goes.
 *
 * ── WHY THE INK MATTERS SEPARATELY ────────────────────────────────────
 *
 * Calligraphy does not stay inside its metrics. Across the 604 fonts the
 * tallest glyph reaches 1.62 em above the baseline and the deepest 0.80 em
 * below — a swash under a final nūn, a maddah stacked over an alif. Both
 * platforms lay the line out from the metrics and then keep only what
 * falls inside the text view: Android's `TextView` clips its drawing to
 * its bounds, and iOS rasterises `drawRect:` into a layer the size of the
 * view. So on a page whose lines sit at their natural height the bottom
 * fifth of an em of the deepest words was simply not drawn. Reported
 * 2026-09-03 as text cut off at the bottom of the line, on Android.
 *
 * Measured over the raw fonts (`head.yMax` / `head.yMin` of every page),
 * with a hair added; `rebuild_fonts_from_layout.py` is where to re-measure.
 */
export const MUSHAF_FONT_ASCENT_EM = 1.2;
export const MUSHAF_FONT_DESCENT_EM = 0.6;
export const MUSHAF_INK_ABOVE_EM = 1.64;
export const MUSHAF_INK_BELOW_EM = 0.82;

/**
 * The padding a line's text view needs above and below its line box so
 * the ink that overshoots the metrics is inside the view, and so drawn.
 *
 * Replays how a line is placed inside `lineHeight`. Both platforms split
 * a positive leading — `lineHeight − (ascent + descent)` — in half above
 * and below (Android's `CustomLineHeightSpan`, iOS's baseline offset). A
 * NEGATIVE leading is where they part: Android still halves it, iOS gives
 * no offset and lets the typesetter take the deficit off one side. So the
 * deficit is assumed to come off EITHER side in full, which over-pads on
 * Android by a few points of transparent view and is right on iOS. The
 * padding is whatever the ink still needs beyond that room, in dp, and
 * zero when the box already holds it.
 */
export function lineInkPadding(
  fontSize: number,
  lineHeight: number,
): { top: number; bottom: number } {
  if (!(fontSize > 0) || !(lineHeight > 0)) return { top: 0, bottom: 0 };
  const metrics = (MUSHAF_FONT_ASCENT_EM + MUSHAF_FONT_DESCENT_EM) * fontSize;
  const leading = lineHeight - metrics;
  const room = leading >= 0 ? leading / 2 : leading;
  const above = MUSHAF_FONT_ASCENT_EM * fontSize + room;
  const below = MUSHAF_FONT_DESCENT_EM * fontSize + room;
  return {
    top: Math.max(0, Math.ceil(MUSHAF_INK_ABOVE_EM * fontSize - above)),
    bottom: Math.max(0, Math.ceil(MUSHAF_INK_BELOW_EM * fontSize - below)),
  };
}

/**
 * How to draw one gap: the size to set the space glyph at, and the letter
 * spacing to add to it. **The letter spacing is never negative.**
 *
 * The gap is a no-break space in AmiriQuran, whose advance is
 * MUSHAF_SPACE_ADVANCE_EM. A line solved for a WIDER space adds the
 * difference as letter spacing, which is what this always did.
 *
 * A line solved for a TIGHTER one used to subtract it — and a third of the
 * mushaf's lines are solved tighter than 0.292 em, because that is what
 * justifying a full line of QPC to the measure asks for. Negative letter
 * spacing is where the missing words came from (issue #6): on the reporter's
 * device the gaps came out at the glyph's own width whatever we asked for, so
 * the line was drawn wider than it was measured for, and Android — which lays
 * a single line out by BREAKING it, between glyphs when nothing else will fit
 * — dropped the last word of it. Every line it happened to was a line asking
 * for a tighter-than-0.292 gap, and no line that asked for a wider one lost
 * anything.
 *
 * So don't ask. Shrink the space glyph instead, and let the letter spacing
 * make up whatever is left, which is then zero or positive by construction.
 * The advance is identical either way, so nothing about the page moves.
 * Scaling DOWN cannot disturb the line box the way scaling up would (a gap
 * set at 2.5x the page size would drag the box's height with it) — and the
 * line height is pinned on the paragraph regardless.
 */
export type MushafGapMetrics = { fontSize: number; letterSpacing: number };

export function gapMetrics(spaceEm: number, fontSize: number): MushafGapMetrics {
  const target = Math.max(0, spaceEm) * fontSize;
  const scale = Math.min(1, Math.max(0, spaceEm) / MUSHAF_SPACE_ADVANCE_EM);
  const gapFontSize = fontSize * scale;
  return {
    fontSize: gapFontSize,
    // Zero when the glyph was shrunk to fit exactly; the surplus when the
    // line wants a gap wider than the glyph. Clamped because a float that
    // lands at -1e-15 is still a negative letter spacing.
    letterSpacing: Math.max(0, target - MUSHAF_SPACE_ADVANCE_EM * gapFontSize),
  };
}

/** Gaps between the words of a line (0 for plate and basmalah lines). */
export function lineGapCount(line: MushafLine): number {
  return line.kind === 'ayah' ? Math.max(0, line.words.length - 1) : 0;
}

/**
 * Per-layout and per-line memo tables.
 *
 * Everything they hold is size-independent: the measure a page is set to, the
 * pieces a line decomposes into. None of it involves the font size, the screen
 * width or the orientation — yet it was all recomputed on every render of
 * every line, which on a fullscreen toggle meant several thousand rebuilds of
 * results that could not have changed. Keyed weakly on the decoded objects,
 * which the decode cache owns, so entries go when a page is evicted.
 */
const measureCache = new WeakMap<MushafPageLayout, number>();
const tokenStreamCache = new WeakMap<MushafLine, MushafLinePiece[]>();

/**
 * The page's measure — the width of its text block, in ems of its own font,
 * as the renderer draws it.
 *
 * NOT `layout.measure`: that is the widest line's advances alone, and a line
 * is drawn with a space between every pair of words. Sizing a page from the
 * advances makes every full line render ~15% wider than the box it was sized
 * for. The measure is the widest line as DRAWN at the nominal space.
 */
export function pageMeasureEm(layout: MushafPageLayout): number {
  const memo = measureCache.get(layout);
  if (memo !== undefined) return memo;
  const value = computePageMeasureEm(layout);
  measureCache.set(layout, value);
  return value;
}

function computePageMeasureEm(layout: MushafPageLayout): number {
  let widest = 0;
  for (const line of layout.lines) {
    if (line.kind !== 'ayah') continue;
    const drawn = line.natural + WORD_SPACE_EM * lineGapCount(line);
    if (drawn > widest) widest = drawn;
  }
  return widest > 0 ? widest : layout.measure;
}

/**
 * The width of the page's text block, in ems — the measure plus the slack
 * every line's box carries. `fontSize = textWidth / pageBlockEm(layout)`, so
 * the widest line spans the measure and its box still ends exactly at the
 * edge of the block. Nothing the renderer draws ever overflows its parent.
 */
export function pageBlockEm(layout: MushafPageLayout): number {
  return pageMeasureEm(layout) + MUSHAF_LINE_BOX_SLACK_EM;
}

/**
 * The space this line is set at, in ems — solved so the line spans the
 * measure exactly, then held inside the band.
 *
 * A line that would need more than the band allows is returned at the nominal
 * space and comes out short; the renderer centres it, which is what the print
 * does with the line that closes a surah and what the fidelity rules mandate
 * for anything else that cannot reach the measure honestly.
 */
export function lineSpaceEm(line: MushafLine, measureEm: number): number {
  if (line.kind !== 'ayah') return WORD_SPACE_EM;
  const gaps = lineGapCount(line);
  if (gaps === 0 || line.centered) return WORD_SPACE_EM;
  const required = (measureEm - line.natural) / gaps;
  if (required > WORD_SPACE_MAX_EM) return WORD_SPACE_EM;
  return required < WORD_SPACE_MIN_EM ? WORD_SPACE_MIN_EM : required;
}

/**
 * Width of a line as drawn, in ems. Never more than the measure — that is the
 * invariant the renderer depends on, since a line wider than its box loses its
 * last word to the platform's single-line truncation.
 */
export function lineWidthEm(line: MushafLine, measureEm: number): number {
  if (line.kind !== 'ayah') return 0;
  return line.natural + lineSpaceEm(line, measureEm) * lineGapCount(line);
}

/**
 * One piece of a drawn line: a run of glyphs, or a gap.
 *
 * A gap is `inner` when it separates the two glyphs of a single token — ~200
 * words across the mushaf carry a hizb or sajdah symbol that way — and the
 * build script budgets those at the nominal space, so the renderer draws them
 * at the nominal space rather than at the line's justified one.
 */
export type MushafLinePiece =
  | { kind: 'glyphs'; text: string; word: MushafWord; index: number }
  | { kind: 'gap'; inner: boolean; index: number };

/**
 * A line, decomposed into what the renderer actually draws.
 *
 * **Every token is treated identically, whatever its glyph count.** That is
 * the whole point of this function existing, because the renderer used to
 * treat them differently: it wrapped multi-glyph tokens in a bidi override
 * (U+202D/U+202C) and left single-glyph tokens bare. QPC numbers its glyphs
 * in reading order, so the bare tokens were already right and it was the
 * override that was wrong — it laid its token out left to right inside a
 * right-to-left line. With the two kinds mixed in one paragraph the bidi
 * algorithm reordered the overridden tokens against their neighbours, and the
 * text of the Quran came out in the wrong order: page 49's rub-el-hizb landed
 * after `وَإِن` instead of before it, and 2:2 read `لَا ۛ فِيهِ ۛ رَيْبَ`.
 *
 * There is no bidi control character in the stream now. The glyphs are in
 * logical order, the paragraph is right-to-left, and the algorithm has one
 * uniform kind of run to lay out — which is the case it gets right.
 */
export function lineTokenStream(line: MushafLine): MushafLinePiece[] {
  const memo = tokenStreamCache.get(line);
  if (memo !== undefined) return memo;
  const value = computeLineTokenStream(line);
  tokenStreamCache.set(line, value);
  return value;
}

function computeLineTokenStream(line: MushafLine): MushafLinePiece[] {
  if (line.kind !== 'ayah') return [];
  const pieces: MushafLinePiece[] = [];
  line.words.forEach((word, i) => {
    if (i > 0) pieces.push({ kind: 'gap', inner: false, index: i });
    word.text.split(' ').forEach((text, k) => {
      if (k > 0) pieces.push({ kind: 'gap', inner: true, index: i });
      pieces.push({ kind: 'glyphs', text, word, index: i });
    });
  });
  return pieces;
}

/** Pages 1–2 are framed plates: centred lines, larger text, own proportions. */
export function isFramedPage(page: number): boolean {
  return page === 1 || page === 2;
}

let raw: RawPage[] | null = null;
const decoded = new Map<number, MushafPageLayout>();

function loadRaw(): RawPage[] {
  if (raw == null) {
    // Required lazily: the mushaf reader is one screen of many, and this is
    // the largest data file in the app.
    raw = require('./data/mushafLayoutV2.json') as RawPage[];
  }
  return raw;
}

/**
 * Bring the layout data in ahead of the reader, off the critical path.
 *
 * Lazy was right — a user who never opens the muṣḥaf should not pay for
 * 1.4 MB of line data at launch. But lazy on its own meant the first
 * `getPageLayout` of a session did the whole require: six hundred pages
 * of words and advances materialised on the JS thread, in the middle of
 * the push transition, for the first page the reader was trying to draw.
 * That was the hitch on the first open of every session.
 *
 * So the screens a reader passes through on the way — the Qur'an tab, the
 * home card that says "Continue" — ask for it after their own interactions
 * are done. By the time the surah is tapped it is already here; and a
 * user who never gets that far still never pays.
 */
export function warmMushafLayout(riwayah?: RiwayahId): void {
  // A bundled riwayah draws from its own line data, not this file; a Warsh
  // reader warming the Ḥafṣ layout would be paying for a muṣḥaf they are
  // not in.
  if (riwayah && riwayahById(riwayah).render === 'unicode') return;
  loadRaw();
}

function decodeLine(line: RawLine): MushafLine | null {
  if (line.t === 's' || line.t === 'b') {
    return {
      kind: line.t === 's' ? 'surah' : 'basmalah',
      surah: line.s ?? 0,
    };
  }
  const tokens = (line.x ?? '').split('|').filter(Boolean);
  const advances = line.a ?? [];
  const words: MushafWord[] = [];
  let i = 0;
  for (const seg of line.w ?? []) {
    const [surah, ayah, first, count, isEnd] = seg;
    for (let k = 0; k < count; k++) {
      const text = tokens[i++];
      if (text == null) break;
      words.push({
        text,
        advance: advances[i - 1] ?? 0,
        surah,
        ayah,
        position: first + k,
        // Only the LAST word of a run flagged `isEnd` is the medallion.
        isEnd: isEnd === 1 && k === count - 1,
      });
    }
  }
  if (words.length === 0) return null;
  return {
    kind: 'ayah',
    words,
    natural: line.n ?? 0,
    centered: line.c === 1,
  };
}

/** Decoded layout for one page, or null when the page is out of range. */
export function getPageLayout(page: number): MushafPageLayout | null {
  const cached = decoded.get(page);
  if (cached) return cached;
  const pages = loadRaw();
  const entry = pages[page - 1];
  if (!entry || entry.p !== page) {
    const found = pages.find(p => p.p === page);
    if (!found) return null;
    return decodePage(found);
  }
  return decodePage(entry);
}

function decodePage(entry: RawPage): MushafPageLayout {
  const cached = decoded.get(entry.p);
  if (cached) return cached;
  const lines = entry.l
    .map(decodeLine)
    .filter((l): l is MushafLine => l != null);
  const layout: MushafPageLayout = {
    page: entry.p,
    measure: entry.m,
    lines,
  };
  decoded.set(entry.p, layout);
  // The reader only ever holds a few pages; keep the decode cache near that.
  if (decoded.size > 24) {
    const oldest = decoded.keys().next().value;
    if (oldest != null && oldest !== entry.p) decoded.delete(oldest);
  }
  return layout;
}

/** Every ayah that appears on a page, in reading order. */
export function ayahsOnPage(page: number): Array<{ surah: number; ayah: number }> {
  const layout = getPageLayout(page);
  if (!layout) return [];
  const out: Array<{ surah: number; ayah: number }> = [];
  for (const line of layout.lines) {
    if (line.kind !== 'ayah') continue;
    for (const w of line.words) {
      const last = out[out.length - 1];
      if (!last || last.surah !== w.surah || last.ayah !== w.ayah) {
        out.push({ surah: w.surah, ayah: w.ayah });
      }
    }
  }
  return out;
}

/** Surahs whose name plate is printed on this page. */
export function surahHeadersOnPage(page: number): number[] {
  const layout = getPageLayout(page);
  if (!layout) return [];
  return layout.lines
    .filter(l => l.kind === 'surah')
    .map(l => (l as { surah: number }).surah);
}

/** Test seam. */
export function _resetLayoutCache(): void {
  decoded.clear();
}
